use strict;
use warnings;
use Test::More;
use Redirects;

subtest benign_control => sub {
    is(Redirects::after_login('/account'), '/account', 'keeps an on-site path');
};

subtest security_rejects_offsite_target => sub {
    is(Redirects::after_login('//evil.example/phish'), '/', 'sends an off-site target home');
};

done_testing();

